cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    half* __restrict__ output,
    int batch_size,
    int in_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding
) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int output_h = blockIdx.z * blockDim.x + threadIdx.x;
    int output_w = threadIdx.y;

    if (batch_idx >= batch_size || channel_idx >= in_channels || 
        output_h >= output_height || output_w >= output_width) {
        return;
    }

    half sum = __float2half(0.0f);

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            int input_h = output_h * stride - padding + kh;
            int input_w = output_w * stride - padding + kw;

            if (input_h >= 0 && input_h < input_height && input_w >= 0 && input_w < input_width) {
                int input_idx = batch_idx * (in_channels * input_height * input_width) +
                               channel_idx * (input_height * input_width) +
                               input_h * input_width + input_w;

                int weight_idx = channel_idx * (kernel_size * kernel_size) + kh * kernel_size + kw;

                sum = __hadd(sum, __hmul(input[input_idx], weight[weight_idx]));
            }
        }
    }

    int output_idx = batch_idx * (in_channels * output_height * output_width) +
                     channel_idx * (output_height * output_width) +
                     output_h * output_width + output_w;

    output[output_idx] = sum;
}

void launch_depthwise_conv2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding
) {
    dim3 block_size(16, 16);
    dim3 grid_size(batch_size, in_channels, (output_height + 15) / 16);

    depthwise_conv2d_kernel<<<grid_size, block_size>>>(
        input, weight, output,
        batch_size, in_channels,
        input_height, input_width,
        output_height, output_width,
        kernel_size, stride, padding
    );
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="depthwise_conv2d",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["launch_depthwise_conv2d"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
            super(ModelNew, self).__init__()
            self.in_channels = in_channels
            self.kernel_size = kernel_size
            self.stride = stride
            self.padding = padding
            self.bias = bias

            # Initialize weights
            self.weight = torch.nn.Parameter(torch.randn(in_channels, kernel_size, kernel_size, dtype=torch.float16))
            if bias:
                self.bias = torch.nn.Parameter(torch.randn(in_channels, dtype=torch.float16))
            else:
                self.register_parameter('bias', None)

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            batch_size, _, input_height, input_width = x.shape

            # Calculate output dimensions
            output_height = (input_height + 2 * self.padding - self.kernel_size) // self.stride + 1
            output_width = (input_width + 2 * self.padding - self.kernel_size) // self.stride + 1

            # Prepare output tensor
            output = torch.empty(batch_size, self.in_channels, output_height, output_width, dtype=torch.float16, device=x.device)

            # Launch CUDA kernel
            module.launch_depthwise_conv2d(
                x.contiguous().data_ptr(),
                self.weight.data_ptr(),
                output.data_ptr(),
                batch_size,
                self.in_channels,
                input_height,
                input_width,
                output_height,
                output_width,
                self.kernel_size,
                self.stride,
                self.padding
            )

            # Add bias if needed
            if self.bias is not None:
                output += self.bias.view(1, -1, 1, 1)

            return output

    return ModelNew

# Create model
ModelNew = compile_and_run()

